/**
 * 图片压缩工具：将上传的图片压缩到合理尺寸和质量，避免 localStorage 配额超限
 */

export interface CompressOptions {
  /** 最大宽度（px），超过则等比缩放 */
  maxWidth?: number;
  /** 最大高度（px），超过则等比缩放 */
  maxHeight?: number;
  /** JPEG 质量 0-1，默认 0.8 */
  quality?: number;
  /** 输出 MIME 类型，默认 image/jpeg */
  mimeType?: string;
}

/**
 * 将 File 压缩为 base64 DataURL
 * - 自动等比缩放到 maxWidth/maxHeight 以内
 * - JPEG 质量压缩
 * - 返回 base64 字符串
 */
export function compressImage(file: File, options: CompressOptions = {}): Promise<string> {
  const {
    maxWidth = 1920,
    maxHeight = 1080,
    quality = 0.8,
    mimeType = 'image/jpeg',
  } = options;

  return new Promise((resolve, reject) => {
    if (!file.type.startsWith('image/')) {
      reject(new Error('Not an image file'));
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        let scale = 1;

        // 计算缩放比例
        if (width > maxWidth) {
          scale = Math.min(scale, maxWidth / width);
        }
        if (height > maxHeight) {
          scale = Math.min(scale, maxHeight / height);
        }

        const targetWidth = Math.round(width * scale);
        const targetHeight = Math.round(height * scale);

        const canvas = document.createElement('canvas');
        canvas.width = targetWidth;
        canvas.height = targetHeight;

        const ctx = canvas.getContext('2d');
        if (!ctx) {
          reject(new Error('Canvas 2D context not available'));
          return;
        }

        // 白色背景（处理透明 PNG 转 JPEG 的黑底问题）
        if (mimeType === 'image/jpeg') {
          ctx.fillStyle = '#000000';
          ctx.fillRect(0, 0, targetWidth, targetHeight);
        }

        ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

        try {
          const dataUrl = canvas.toDataURL(mimeType, quality);
          resolve(dataUrl);
        } catch (err) {
          reject(err);
        }
      };
      img.onerror = () => reject(new Error('Failed to decode image'));
      img.src = e.target?.result as string;
    };
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

/**
 * 估算 base64 字符串的原始字节大小
 * base64 每 4 个字符代表 3 个字节
 */
export function estimateBase64Size(base64: string): number {
  const base64Part = base64.split(',')[1] ?? base64;
  const padding = base64Part.endsWith('==') ? 2 : base64Part.endsWith('=') ? 1 : 0;
  return Math.round((base64Part.length * 3) / 4 - padding);
}

/**
 * 格式化文件大小为人类可读字符串
 */
export function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

/** 兼容别名，旧代码可能使用 formatBytes */
export const formatBytes = formatFileSize;

/**
 * 对已有的 base64 DataURL 图片重新压缩
 * - 用于数据迁移（历史上传的大图自动压缩）
 * - 用于一键压缩功能
 * - 如果输入不是 base64（是外部 URL 或相对路径），直接原样返回
 */
export async function compressBase64(
  dataUrl: string,
  options: CompressOptions = {},
): Promise<string> {
  // 非 base64 图片（URL 路径），不处理
  if (!dataUrl || !dataUrl.startsWith('data:image/')) {
    return dataUrl;
  }

  const { maxWidth = 1600, maxHeight = 1200, quality = 0.7, mimeType = 'image/jpeg' } = options;

  // 如果图片已经很小（< 80KB），没必要再压缩
  const currentSize = estimateBase64Size(dataUrl);
  const MIN_SIZE_BEFORE_RECOMPRESS = 80 * 1024; // 80KB
  if (currentSize < MIN_SIZE_BEFORE_RECOMPRESS) {
    return dataUrl;
  }

  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      let { width, height } = img;
      let scale = 1;

      if (width > maxWidth) scale = Math.min(scale, maxWidth / width);
      if (height > maxHeight) scale = Math.min(scale, maxHeight / height);

      const targetWidth = Math.round(width * scale);
      const targetHeight = Math.round(height * scale);

      // 如果尺寸不需要缩放 且 目标质量 >= 0.8 且 当前大小已经低于目标（粗略估计），跳过
      // 注意：quality 影响文件大小但很难准确预测，保守起见：
      // 只有当 scale=1 且 quality >= 0.9 且大小 < 150KB 时才跳过，避免本应压缩的图被跳过
      if (scale > 0.98 && quality >= 0.9 && currentSize < 150 * 1024) {
        resolve(dataUrl);
        return;
      }

      const canvas = document.createElement('canvas');
      canvas.width = targetWidth;
      canvas.height = targetHeight;

      const ctx = canvas.getContext('2d');
      if (!ctx) {
        reject(new Error('Canvas 2D context not available'));
        return;
      }

      if (mimeType === 'image/jpeg') {
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, targetWidth, targetHeight);
      }

      ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

      try {
        const result = canvas.toDataURL(mimeType, quality);
        resolve(result);
      } catch (err) {
        reject(err);
      }
    };
    img.onerror = () => reject(new Error('Failed to decode base64 image'));
    img.src = dataUrl;
  });
}
